<?php include 'includes/header.php'; $items=read_json('businesses.json'); $cat=isset($_GET['cat'])?$_GET['cat']:''; $cats=categories_from($items); ?><section class="page-hero"><h1>Guia Comercial</h1><p>Empresas, gastronomia, hospedagem e serviços locais cadastrados no guia digital da cidade.</p></section><div class="search-card"><input data-search placeholder="Buscar empresas..."><button>Buscar</button></div><div class="filters"><a class="filter <?= $cat==''?'active':'' ?>" href="guia-comercial.php">Todos</a><?php foreach($cats as $c): ?><a class="filter <?= $cat==$c?'active':'' ?>" href="guia-comercial.php?cat=<?= urlencode($c) ?>"><?= h($c) ?></a><?php endforeach; ?></div><section class="section"><div class="commercial-grid"><?php $count=0; foreach($items as $b): if($cat && ($b['categoria'] ?? '') !== $cat) continue; $count++; ?><article class="commercial-card" data-card><img loading="lazy" decoding="async" src="<?= h(img_url('empresas',($b['imagem'] ?? ''))) ?>" alt="<?= h(($b['nome'] ?? '')) ?>"><div class="biz-body"><span class="pill"><?= h(($b['categoria'] ?? '')) ?></span><h3><?= h(($b['nome'] ?? '')) ?></h3><p><?= h(($b['descricao'] ?? '')) ?></p><div class="small-actions"><span class="free-profile">Cadastro básico</span><a href="<?= h(maps_link($b)) ?>" target="_blank">Ver no mapa</a></div></div></article><?php endforeach; if(!$count): ?><div class="empty">Nenhum estabelecimento cadastrado nesta categoria.</div><?php endif; ?></div></section><section class="info-card"><h2>Solicitar inclusão no guia</h2><p>Estabelecimentos locais poderão solicitar inclusão no guia, sujeitos à validação da equipe responsável e às regras institucionais definidas para o projeto.</p><a class="btn green" href="cadastro-empresa.php">Solicitar inclusão</a></section><?php include 'includes/footer.php'; ?>
